cat > s3.mjs <<'EOF'
import { go } from './login.mjs';
const {b,p}=await go();
await p.goto('http://127.0.0.1:54569/integrations');
await p.click('#gen');
await p.waitForFunction(()=>!document.getElementById('toast').hidden);
const text = await p.innerText('#toast');
console.log('TOAST:', text);
const key = text.replace('New signing key (shown once): ','').trim();
await p.goto('http://127.0.0.1:54569/webhooks');
await p.fill('#secret', key);
await p.click('#save');
await p.waitForFunction(()=>document.getElementById('done').textContent.includes('saved'));
console.log('saved; field =', await p.inputValue('#secret'), 'match=', (await p.inputValue('#secret'))===key);
await b.close();
EOF
node s3.mjs
